inline constexpr std::optional<int> parse_int(std::string_view s)
{
   if (s.empty()) {
      return std::nullopt;
   }
   int value;
   auto result = std::from_chars(s.data(), s.data() + s.size(), value);
   if (result.ec == std::errc()) {
      return value;
   }
   return std::nullopt;
}
